// ============================================================
// 60103 纯 JS 计算（配置来自飞书，订单来自 ERP）
// ============================================================
function itemsOf(nodeName, fallbackKey) {
  try {
    const it = $(nodeName).first().json;
    const list = it.items || it[fallbackKey] || it;
    return (Array.isArray(list) ? list : []).map(r => flat(r.fields || r));
  } catch (e) { return []; }
}

// ---- 1. 配置 ----
const cfgRaw = {
  '商品配置': itemsOf('商品配置'),
  '运价表': itemsOf('运价表'),
  '澳洲分区': itemsOf('澳洲分区'),
  '全局参数': itemsOf('全局参数'),
  '国家规则': itemsOf('国家规则')
};

// ---- 2. 订单（ERP 返回结构兼容）----
let raw = $('① 拉 ERP 订单').first().json;
['data', 'rows', 'orders', 'items', 'result', 'records'].forEach(k => {
  if (raw[k] !== undefined && (Array.isArray(raw[k]) || typeof raw[k] === 'object')) raw = raw[k];
});
if (!Array.isArray(raw)) raw = [raw];

// ERP 字段 → 内部字段（按你 ERP 实际字段名改这里）
const MAP = {
  '交易编号': ['交易编号', 'trade_no', 'tradeNo', 'order_no_series'],
  '订单编号': ['订单编号', 'order_no', 'orderNo', 'shopify_order_no'],
  'SKU': ['SKU', 'sku', 'sku_code', 'item_sku'],
  '商品数量': ['商品数量', 'qty', 'quantity', 'num'],
  '国家中文': ['国家中文', '国家', 'country', 'country_cn', 'country_name'],
  '物流公司': ['物流公司', 'logistics_company', 'carrier'],
  '物流渠道': ['物流渠道', 'logistics_channel', 'channel', 'shipping_method'],
  '内部单号': ['内部单号', 'inner_no', 'tracking_no', 'tracking_number'],
  '邮政编码': ['邮政编码', '邮编', 'postcode', 'zip', 'zip_code'],
  '原始图片': ['原始图片', 'image', 'image_url', 'picture']
};
const pick = (row, names) => {
  for (const n of names) {
    const v = row[n];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v);
  }
  return '';
};
const ordersRaw = raw.map(r => {
  const o = {};
  for (const [t, names] of Object.entries(MAP)) o[t] = pick(r, names);
  return o;
});

if (!ordersRaw.length) throw new Error('ERP 没有返回订单');
const noSku = ordersRaw.filter(r => !r['SKU']).length;
const noTxn = ordersRaw.filter(r => !r['交易编号']).length;
if (noSku) throw new Error(`有 ${noSku} 行没取到 SKU，检查字段映射`);
if (noTxn) throw new Error(`有 ${noTxn} 行没取到交易编号，检查字段映射`);

// ---- 3. 计算 ----
// ---------------- 工具 ----------------
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

// numpy 的 round 是「银行家舍入」（.5 取偶），这里保持一致
function npRound(x, d = 0) {
  if (x === null || x === undefined || !Number.isFinite(x)) return x;
  const m = Math.pow(10, d);
  const a = Math.abs(x) * m;
  const f = Math.floor(a);
  const diff = a - f;
  let r;
  if (diff > 0.5) r = f + 1;
  else if (diff < 0.5) r = f;
  else r = (f % 2 === 0) ? f : f + 1;
  return Math.sign(x) * (r / m);
}

const numOr = (v, dflt) => (num(v) === null ? dflt : num(v));

// 展平飞书字段（Lark 节点返回的可能是 {text:...}/{name:...}）
function core(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number' || typeof v === 'boolean') return v;
  if (typeof v === 'string') return v.trim() || null;
  if (Array.isArray(v)) {
    const a = v.map(core).filter(x => x !== null);
    return a.length === 1 ? a[0] : a;
  }
  if (typeof v === 'object') {
    for (const k of ['text', 'name', 'value', 'link', 'url']) {
      if (v[k] !== undefined && v[k] !== null) return core(v[k]);
    }
    if (v.values !== undefined) return core(v.values);
  }
  return String(v);
}
function flat(fields) {
  const o = {};
  for (const [k, v] of Object.entries(fields || {})) o[String(k).trim()] = core(v);
  return o;
}

// ---------------- 1. 读配置 ----------------
function buildConfig(cfgRaw) {
  const params = {};
  for (const r of cfgRaw['全局参数'] || []) {
    const k = String(r['参数键'] || '').trim();
    if (!k) continue;
    const v = num(r['参数值']);
    params[k] = v === null ? String(r['参数值'] ?? '') : v;
  }
  const P = (k, d) => (typeof params[k] === 'number' ? params[k] : d);

  // 商品配置：前缀(可逗号多别名) → 配置
  const products = new Map();
  for (const r of cfgRaw['商品配置'] || []) {
    const cell = String(r['SKU前缀'] ?? '').trim();
    if (!cell) continue;
    const aliases = cell.split(/[,，、]/).map(s => s.trim()).filter(Boolean);
    const row = {
      main: aliases[0],
      buy: num(r['采购价']),
      buyR: num(r['偏远采购价']),
      dom: num(r['国内运费']),
      domR: num(r['偏远国内运费']),
      wt: num(r['重量']),
      svc: num(r['服务费']),
      svcUS: num(r['服务费_美国']),
      pack: numOr(r['每计费单位件数'], 1),
      ovC: r['运价覆盖_国家'] ? String(r['运价覆盖_国家']).trim() : null,
      ovP: num(r['运价覆盖_公斤价']),
      ovF: num(r['运价覆盖_挂号费']),
      fixed: num(r['账单固定金额']),
    };
    for (const a of aliases) {
      if (products.has(a)) throw new Error(`前缀「${a}」在商品配置里重复`);
      products.set(a, row);
    }
  }
  const prefixes = [...products.keys()].sort((a, b) => b.length - a.length);

  // 运价表：国家 → [{lo,hi,p,fee}] 升序
  const rates = new Map();
  const margins = new Map();
  for (const r of cfgRaw['运价表'] || []) {
    const c = String(r['国家'] ?? '').trim();
    const lo = num(r['下界']), hi = num(r['上界']);
    const p = num(r['公斤价']), fee = num(r['挂号费']);
    if (!c || lo === null || hi === null || p === null) continue;
    if (!rates.has(c)) rates.set(c, []);
    rates.get(c).push({ lo, hi, p, fee });
    if (!margins.has(c) && num(r['毛利']) !== null) margins.set(c, num(r['毛利']));
  }
  for (const arr of rates.values()) arr.sort((a, b) => a.lo - b.lo);

  // 澳洲分区
  const au = new Map();
  for (const r of cfgRaw['澳洲分区'] || []) {
    const z = String(r['邮编'] ?? '').trim().padStart(4, '0');
    const zone = num(r['分区']);
    if (z.length === 4 && zone !== null && !au.has(z)) au.set(z, zone);
  }

  // 国家规则
  const country = new Map();
  for (const r of cfgRaw['国家规则'] || []) {
    const c = String(r['国家'] ?? '').trim();
    if (!c) continue;
    if (String(r['状态'] || '生效').trim() !== '生效') continue;
    country.set(c, {
      isEU: String(r['是否欧盟'] || '否').trim() === '是',
      surcharge: numOr(r['订单附加费'], 0),
      service: num(r['服务费覆盖']),
    });
  }

  return { params, P, products, prefixes, rates, margins, au, country };
}

// ---------------- 2. 订单清洗 ----------------
const ORDER_FILL = ['交易编号', '订单编号', '国家', '物流公司', '物流渠道', '内部单号', '邮编'];

function normalizeOrders(rows) {
  rows = (rows || []).map(r => {
    const o = {};
    for (const [k, v] of Object.entries(r)) o[String(k).trim()] = v === null || v === undefined ? '' : String(v);
    return o;
  });
  // 列名兼容
  for (const r of rows) {
    if (r['国家中文'] !== undefined && !r['国家']) r['国家'] = r['国家中文'];
    if (r['邮政编码'] !== undefined && !r['邮编']) r['邮编'] = r['邮政编码'];
  }
  let out = [];
  let last = {};
  let lastTxn = null;
  for (const r of rows) {
    if (!String(r['SKU'] ?? '').trim()) continue;
    const o = { ...r };
    for (const c of ORDER_FILL) {
      if (o[c] === undefined) o[c] = '';
      if (!String(o[c]).trim()) o[c] = last[c] ?? '';
      else last[c] = o[c];
    }
    // 交易编号变了 → 重置 ffill 源
    if (o['交易编号'] !== lastTxn) { last = { ...o }; lastTxn = o['交易编号']; }
    o['商品数量'] = numOr(o['商品数量'], 1);
    o['_首行'] = o['交易编号'] !== (out.length ? out[out.length - 1]['交易编号'] : null);
    out.push(o);
  }
  out.forEach((o, i) => { o['源表行号'] = i + 1; });
  return out;
}

// ---------------- 3. 匹配 + 算钱 ----------------
function run(cfgRaw, rawOrders) {
  const cfg = buildConfig(cfgRaw);
  const FX = cfg.P('USD_CNY', 6.65);
  const MULT = cfg.P('DEFAULT_SERVICE_FEE', 1.15);
  const EU_TAX = npRound(cfg.P('EU_TAX_EUR', 3) / cfg.P('EUR_USD', 0.9), 2);
  const WEIGHT_FB = cfg.P('WEIGHT_FALLBACK', 0.17);
  const BUY_FB = cfg.P('BUY_FALLBACK', 15);
  const DOM_FB = cfg.P('DOMESTIC_FALLBACK', 4);
  const NON_GOODS = String(cfg.P('NON_GOODS_PREFIX', 'SHIP') || 'SHIP').toUpperCase();
  const ROUND = cfg.P('BILL_ROUND', 2);

  const rows = normalizeOrders(rawOrders);

  // ---- ① 国家改写 ----
  for (const r of rows) {
    r['国家'] = String(r['国家'] || '').trim();
    if (r['国家'] === '美国' && String(r['物流渠道'] || '').includes('岛屿')) r['国家'] = '美国（偏远）';
    r['偏远'] = r['国家'] === '美国（偏远）';
  }
  for (const r of rows) {
    if (r['国家'] !== '澳大利亚') continue;
    const pc = String(r['邮编'] || '').replace(/\D/g, '').padStart(4, '0').slice(-4);
    const z = cfg.au.get(pc);
    r['国家'] = z ? `澳大利亚（${z}区）` : '澳大利亚';
  }

  // ---- ② SKU 前缀匹配 ----
  for (const r of rows) {
    const sku = String(r['SKU'] || '').trim();
    let hit = null;
    for (const p of cfg.prefixes) {
      if (sku === p || sku.startsWith(p + '-') || sku.startsWith(p + '_')) { hit = p; break; }
    }
    r['前缀'] = hit;
    const c = hit ? cfg.products.get(hit) : null;
    r['主前缀'] = c ? c.main : null;
    r['采购价'] = c ? c.buy : null;
    r['国内运费'] = c ? c.dom : null;
    r['重量'] = c ? c.wt : null;
    r['服务费'] = c ? c.svc : null;
    r['服务费_美国'] = c ? c.svcUS : null;
    r['每计费件数'] = c ? (c.pack || 1) : 1;
    r['运价覆盖_国家'] = c ? c.ovC : null;
    r['运价覆盖_公斤价'] = c ? c.ovP : null;
    r['运价覆盖_挂号费'] = c ? c.ovF : null;
    r['账单固定金额'] = c ? c.fixed : null;
  }
  for (const r of rows) {
    if (r['偏远'] && r['采购价'] === null) { /* 用偏远列 */ }
    if (r['偏远'] && cfg.products.get(r['前缀'] || '')?.buyR !== null
        && cfg.products.get(r['前缀'] || '')?.buyR !== undefined) {
      r['采购价'] = cfg.products.get(r['前缀']).buyR;
    }
    if (r['偏远'] && cfg.products.get(r['前缀'] || '')?.domR !== null
        && cfg.products.get(r['前缀'] || '')?.domR !== undefined) {
      r['国内运费'] = cfg.products.get(r['前缀']).domR;
    }
    r['价格缺失'] = r['前缀'] !== null && r['采购价'] === null;
    r['采购价'] = r['采购价'] === null ? BUY_FB : r['采购价'];
    r['国内运费'] = r['国内运费'] === null ? DOM_FB : r['国内运费'];
    r['重量'] = r['重量'] === null ? WEIGHT_FB : r['重量'];
    r['每计费件数'] = Math.max(1, r['每计费件数'] || 1);

    const noImg = !String(r['原始图片'] || '').trim();
    r['非实物'] = String(r['SKU'] || '').toUpperCase().startsWith(NON_GOODS) && noImg;
    if (r['非实物']) { r['采购价'] = 0; r['国内运费'] = 0; r['重量'] = 0; r['价格缺失'] = false; }
  }

  // ---- ③ 运价匹配（逐行）----
  const orderWeight = new Map();
  for (const r of rows) {
    r['行重量'] = r['商品数量'] * r['重量'];
    orderWeight.set(r['交易编号'], (orderWeight.get(r['交易编号']) || 0) + r['行重量']);
  }
  for (const k of orderWeight.keys()) orderWeight.set(k, npRound(orderWeight.get(k), 3));

  const segPrice = new Map();
  for (const r of rows) {
    if (r['_首行']) {
      const w = orderWeight.get(r['交易编号']);
      const arr = cfg.rates.get(r['国家']);
      let hit = null;
      if (arr) for (const s of arr) if (s.lo < w && w <= s.hi) { hit = s; break; }
      segPrice.set(r['交易编号'], hit);
    }
  }
  for (const r of rows) {
    r['订单重量'] = orderWeight.get(r['交易编号']);
    const seg = segPrice.get(r['交易编号']) || null;
    const useOv = r['运价覆盖_国家'] && r['运价覆盖_国家'] === r['国家'] && r['运价覆盖_公斤价'] !== null;
    r['公斤价'] = useOv ? r['运价覆盖_公斤价'] : (seg ? seg.p : null);
    r['挂号费'] = useOv ? (r['运价覆盖_挂号费'] !== null ? r['运价覆盖_挂号费'] : (seg ? seg.fee : null))
                        : (seg ? seg.fee : null);
    const fixed = r['账单固定金额'] !== null;
    r['行缺价'] = !fixed && r['行重量'] > 0 && r['公斤价'] === null;
  }
  const blocked = new Set();
  for (const r of rows) if (r['行缺价']) blocked.add(r['交易编号']);
  for (const r of rows) r['缺运价'] = blocked.has(r['交易编号']);

  // ---- ④ 算钱 ----
  for (const r of rows) {
    const isUS = String(r['国家']).startsWith('美国');
    const rule = cfg.country.get(r['国家']) || {};
    let svc = null;
    if (isUS && r['服务费_美国'] !== null) svc = r['服务费_美国'];
    else if (r['服务费'] !== null) svc = r['服务费'];
    else if (rule.service !== null && rule.service !== undefined) svc = rule.service;
    else svc = cfg.margins.has(r['国家']) ? cfg.margins.get(r['国家']) : MULT;
    r['服务费'] = svc;
    r['附加费'] = rule.surcharge ?? 0;
    r['欧盟税'] = rule.isEU ? EU_TAX : 0;
  }

  // 运费行：同单第一个非固定金额商品
  const freightRow = new Set();
  const byOrder = new Map();
  for (const r of rows) {
    if (!byOrder.has(r['交易编号'])) byOrder.set(r['交易编号'], []);
    byOrder.get(r['交易编号']).push(r);
  }
  for (const [txn, g] of byOrder) {
    const cand = g.find(x => x['账单固定金额'] === null);
    if (cand) freightRow.add(cand);
  }

  // 国内运费份数：同单同 SKU
  const skuQty = new Map();
  for (const r of rows) {
    const k = r['交易编号'] + '||' + r['SKU'];
    skuQty.set(k, (skuQty.get(k) || 0) + r['商品数量']);
  }
  const skuSeen = new Set();

  for (const r of rows) {
    const isFixed = r['账单固定金额'] !== null;
    const isFreight = freightRow.has(r);
    r['运费行'] = isFreight;

    r['行运费'] = isFixed ? 0 : (r['公斤价'] === null ? 0 : r['公斤价'] * r['行重量']);
    r['挂号费合计'] = isFreight && r['挂号费'] !== null ? r['挂号费'] : 0;
    r['运费'] = r['行运费'] + r['挂号费合计'];

    const k = r['交易编号'] + '||' + r['SKU'];
    const first = !skuSeen.has(k);
    skuSeen.add(k);
    r['国内运费份数'] = first ? Math.ceil(skuQty.get(k) / r['每计费件数']) : 0;
    r['国内运费合计'] = r['国内运费'] * r['国内运费份数'];
    if (r['非实物']) { r['国内运费份数'] = 0; r['国内运费合计'] = 0; }

    r['人民币'] = (r['运费'] + r['商品数量'] * r['采购价'] + r['国内运费合计']
                   + (r['_首行'] ? r['附加费'] : 0)) * r['服务费'];
    r['美元'] = r['人民币'] / FX;

    if (isFixed) {
      r['固定金额合计'] = npRound(r['账单固定金额'] * r['国内运费份数'], 6);
      r['人民币'] = r['固定金额合计'] * FX;
      r['美元'] = r['人民币'] / FX;
    }
  }

  // 账单金额
  const usdSum = new Map();
  for (const r of rows) usdSum.set(r['交易编号'], (usdSum.get(r['交易编号']) || 0) + r['美元']);
  for (const r of rows) {
    r['账单金额'] = npRound(usdSum.get(r['交易编号']) + r['欧盟税'], ROUND);
  }

  return { rows, cfg, FX, EU_TAX, MULT };
}

// ---------------- 4. 汇总 + 缺失 ----------------
function summarize(rows, cfg, FX) {
  const byOrder = new Map();
  for (const r of rows) {
    if (!byOrder.has(r['交易编号'])) byOrder.set(r['交易编号'], []);
    byOrder.get(r['交易编号']).push(r);
  }
  const perOrder = [];
  for (const [txn, g] of byOrder) {
    const h = g[0];
    if (h['缺运价']) continue;
    perOrder.push({
      国家: h['国家'], 交易编号: txn,
      件数: g.filter(x => !x['非实物']).reduce((s, x) => s + x['商品数量'], 0),
      总重量: h['订单重量'],
      国际运费: g.reduce((s, x) => s + x['运费'], 0),
      国内运费: g.reduce((s, x) => s + x['国内运费合计'], 0),
      采购价: g.reduce((s, x) => s + x['商品数量'] * x['采购价'], 0),
      附加费: h['附加费'],
      欧盟税: npRound(h['欧盟税'] * FX, 2),
      账单合计: h['账单金额'],
    });
  }
  const groups = new Map();
  for (const o of perOrder) {
    if (!groups.has(o.国家)) groups.set(o.国家, []);
    groups.get(o.国家).push(o);
  }
  const summary = [];
  for (const [c, list] of groups) {
    summary.push({
      国家: c,
      订单数: new Set(list.map(x => x.交易编号)).size,
      件数: list.reduce((s, x) => s + x.件数, 0),
      总重量: npRound(list.reduce((s, x) => s + x.总重量, 0), 2),
      国际运费: npRound(list.reduce((s, x) => s + x.国际运费, 0), 2),
      国内运费: npRound(list.reduce((s, x) => s + x.国内运费, 0), 2),
      采购价: npRound(list.reduce((s, x) => s + x.采购价, 0), 2),
      附加费: npRound(list.reduce((s, x) => s + x.附加费, 0), 2),
      欧盟税: npRound(list.reduce((s, x) => s + x.欧盟税, 0), 2),
      账单合计: npRound(list.reduce((s, x) => s + x.账单合计, 0), 2),
    });
  }
  const total = {
    国家: '合计',
    订单数: summary.reduce((s, x) => s + x.订单数, 0),
    件数: summary.reduce((s, x) => s + x.件数, 0),
    总重量: npRound(summary.reduce((s, x) => s + x.总重量, 0), 2),
    国际运费: npRound(summary.reduce((s, x) => s + x.国际运费, 0), 2),
    国内运费: npRound(summary.reduce((s, x) => s + x.国内运费, 0), 2),
    采购价: npRound(summary.reduce((s, x) => s + x.采购价, 0), 2),
    附加费: npRound(summary.reduce((s, x) => s + x.附加费, 0), 2),
    欧盟税: npRound(summary.reduce((s, x) => s + x.欧盟税, 0), 2),
    账单合计: npRound(summary.reduce((s, x) => s + x.账单合计, 0), 2),
  };
  return { summary, total };
}

function findMissing(rows) {
  const missingSku = new Map();
  for (const r of rows) {
    if (r['前缀'] !== null) continue;
    const head = String(r['SKU'] || '').split('_')[0];
    const parts = head.split('-');
    const guess = parts.length >= 2 ? parts.slice(0, 2).join('-') : head;
    const m = missingSku.get(guess) || { 类型: 'SKU', 标识: guess, 建议前缀: guess, 订单数: 0, 行数: 0, SKU集合: new Set(), 样例: r['交易编号'] };
    m.行数 += 1;
    m.SKU集合.add(r['SKU']);
    missingSku.set(guess, m);
  }
  const byOrder = new Map();
  for (const r of rows) {
    if (!byOrder.has(r['交易编号'])) byOrder.set(r['交易编号'], []);
    byOrder.get(r['交易编号']).push(r);
  }
  const missingRate = [];
  for (const [txn, g] of byOrder) {
    if (!g[0]['缺运价']) continue;
    const c = g[0]['国家'], w = g[0]['订单重量'];
    missingRate.push({ 类型: '运价', 标识: `${c}|${w}kg`, 建议前缀: '', 订单数: 1, 行数: 1, 样例交易编号: txn, 说明: `需要覆盖 ${w}kg 的运价段` });
  }
  const missingSkuArr = [...missingSku.values()].map(m => ({
    类型: 'SKU', 标识: m.标识, 建议前缀: m.建议前缀,
    订单数: 0, 行数: m.行数, SKU数: m.SKU集合.size,
    样例交易编号: m.样例,
    说明: `商品配置里没有前缀「${m.标识}」，需补一行（${m.SKU集合.size} 个尺码在用）`,
  }));
  return [...missingSkuArr, ...missingRate];
}


